from pathlib import Path
import datetime,gzip,hashlib,json,subprocess,sys
out=Path(__file__).resolve().parents[1];root=Path.cwd();phase=sys.argv[1];assert phase in ['before','after'];b=json.load(gzip.open(out/'before.json.gz'));sha=lambda p:hashlib.sha256(Path(p).read_bytes()).hexdigest();hashes=b['hashes'] if phase=='before' else {p:sha(p) for p in b['hashes']};assert all(sha(p)==h for p,h in hashes.items());src=out/'workers/public_measure.rs';lib=root/'target/debug/libtypst_core.rlib';binary=Path('/tmp/tekt-table-cells-public-'+phase);cmd=['rustc','--edition=2021',str(src),'-L','dependency='+str(root/'target/debug/deps'),'--extern','typst_core='+str(lib),'-o',str(binary)];record=dict(start=datetime.datetime.now(datetime.timezone.utc).isoformat(),head=b['head'],source_hashes=hashes,probe_source_sha256=sha(src),library_sha256=sha(lib),command=cmd);r=subprocess.run(cmd,capture_output=True,text=True);record.update(build_exit=r.returncode,build_stderr=r.stderr);(out/('public-'+phase+'.json')).write_text(json.dumps(record,indent=2)+'\n');assert r.returncode==0,r.stderr;r=subprocess.run([str(binary)],capture_output=True,text=True);record.update(exit=r.returncode,stdout=r.stdout,stderr=r.stderr,binary_sha256=sha(binary),sources_unchanged=all(sha(p)==h for p,h in hashes.items()),end=datetime.datetime.now(datetime.timezone.utc).isoformat());(out/('public-'+phase+'.json')).write_text(json.dumps(record,indent=2)+'\n');assert r.returncode==0 and record['sources_unchanged'];print(r.stdout,flush=True)
